import pandas as pd

prices = {
    'C': 0.5, 'Mn': 2, 'Si': 2.2, 'Cr': 9, 'Ni': 17, 'Mo': 25, 
    'V': 30, 'Nb': 45, 'Co': 33, 'Al': 2.4, 'Ti': 12, 'Cu': 9
}

def calc_cost(row):
    return sum(row[el] * price for el, price in prices.items())

pool_df = pd.read_csv('alloy_pair_constrained_pool.csv')
pool_df['cost'] = pool_df.apply(calc_cost, axis=1)

candidates = ['c092', 'c007', 'c044', 'c075', 'c019']
for c in candidates:
    row = pool_df[pool_df['candidate_id'] == c].iloc[0]
    print(f"{c}: Mo={row['Mo']:.3f}, Cost={row['cost']:.3f}")

print("\nAnd c068 just in case:")
row = pool_df[pool_df['candidate_id'] == 'c068'].iloc[0]
print(f"c068: Mo={row['Mo']:.3f}, Cost={row['cost']:.3f}")

